local SackStitcherMaker = {}
local PRODUCTS = {
    iron_sackstitcher = { name = "Železni sivec za vrecke", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni sivec za vrecke za mlinarje." },
    bronze_sackstitcher = { name = "Bronast sivec za vrecke", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast sivec za vrecke za mlinarje." },
    silver_sackstitcher = { name = "Srebrn sivec za vrecke", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn sivec za vrecke za mlinarje." },
    gilded_sackstitcher = { name = "Pozlačen sivec za vrecke", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen sivec za vrecke za mlinarje." },
    jewel_set_sackstitcher = { name = "Draguljast sivec za vrecke", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast sivec za vrecke za mlinarje." },
    royal_sovereign_sackstitcher = { name = "Kraljevski suveren sivec za vrecke", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren sivec za vrecke z biseri za krono." },
}
local BUILDINGS = {
    sackstitcher_workshop = { name = "Sackstitcher delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    sackstitcher_house = { name = "Sackstitcher hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_sackstitcher_atelier = { name = "Mojstrski sackstitcher atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_sackstitcher_palace = { name = "Suverena sackstitcher palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SackStitcherMaker.ironStock = 14; SackStitcherMaker.bronzeStock = 12; SackStitcherMaker.woodStock = 12; SackStitcherMaker.leatherStock = 12; SackStitcherMaker.silverStock = 8; SackStitcherMaker.goldStock = 6; SackStitcherMaker.jewelStock = 4; SackStitcherMaker.pearlStock = 4
SackStitcherMaker.productStock = {}; SackStitcherMaker.buildings = {}; SackStitcherMaker.maker = nil; SackStitcherMaker.activeMaking = {}; SackStitcherMaker.totalProducts = 0; SackStitcherMaker.dayTimer = 0
function SackStitcherMaker.init() SackStitcherMaker.ironStock=14; SackStitcherMaker.bronzeStock=12; SackStitcherMaker.woodStock=12; SackStitcherMaker.leatherStock=12; SackStitcherMaker.silverStock=8; SackStitcherMaker.goldStock=6; SackStitcherMaker.jewelStock=4; SackStitcherMaker.pearlStock=4; SackStitcherMaker.productStock={}; SackStitcherMaker.buildings={}; SackStitcherMaker.maker=nil; SackStitcherMaker.activeMaking={}; SackStitcherMaker.totalProducts=0; SackStitcherMaker.dayTimer=0; print("[SackStitcherMaker] Royal Sack Stitcher Maker System initialized (6 products, 4 buildings)") end
function SackStitcherMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SackStitcherMaker.maker={name=n or ("Sivar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sivar najet: %s (spretnost: %d)",SackStitcherMaker.maker.name,s),"success") end; return true end
function SackStitcherMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SackStitcherMaker.build(id) local ok,e=SackStitcherMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SackStitcherMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SackStitcherMaker.getQualityBonus() local b=0; for _,bd in ipairs(SackStitcherMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SackStitcherMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SackStitcherMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SackStitcherMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SackStitcherMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SackStitcherMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SackStitcherMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SackStitcherMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SackStitcherMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SackStitcherMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SackStitcherMaker.buildings==0 then return false,"Potrebna sivalna delavnica" end; if not SackStitcherMaker.maker then return false,"Potreben sivar" end; return true end
function SackStitcherMaker.make(pt,qty) qty=qty or 1; local ok,e=SackStitcherMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SackStitcherMaker.ironStock=SackStitcherMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SackStitcherMaker.bronzeStock=SackStitcherMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SackStitcherMaker.woodStock=SackStitcherMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SackStitcherMaker.leatherStock=SackStitcherMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SackStitcherMaker.silverStock=SackStitcherMaker.silverStock-d.silverCost*qty end; if d.goldCost then SackStitcherMaker.goldStock=SackStitcherMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SackStitcherMaker.jewelStock=SackStitcherMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SackStitcherMaker.pearlStock=SackStitcherMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SackStitcherMaker.maker then t=math.max(1,t-math.floor(SackStitcherMaker.maker.skill/13)) end; table.insert(SackStitcherMaker.activeMaking,{id="${MAKER_LOWER}_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SackStitcherMaker.completeMaking(m) local q=1.0+(SackStitcherMaker.getQualityBonus()/100); if SackStitcherMaker.maker then q=q+(SackStitcherMaker.maker.skill/140) end; q=math.min(2.5,q); SackStitcherMaker.productStock[m.productType]=(SackStitcherMaker.productStock[m.productType] or 0)+m.quantity; SackStitcherMaker.totalProducts=SackStitcherMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SackStitcherMaker.maker then SackStitcherMaker.maker.itemsMade=SackStitcherMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SackStitcherMaker.maker.skill=math.min(100,SackStitcherMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sivec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"${MAKER_LOWER}.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function SackStitcherMaker.update(dt) if not _G.state then return end; SackStitcherMaker.dayTimer=SackStitcherMaker.dayTimer+dt; if SackStitcherMaker.dayTimer>=30 then SackStitcherMaker.dayTimer=0; for i=#SackStitcherMaker.activeMaking,1,-1 do local m=SackStitcherMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SackStitcherMaker.completeMaking(m); table.remove(SackStitcherMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SackStitcherMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SackStitcherMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SackStitcherMaker.getStats() return {ironStock=SackStitcherMaker.ironStock,bronzeStock=SackStitcherMaker.bronzeStock,woodStock=SackStitcherMaker.woodStock,leatherStock=SackStitcherMaker.leatherStock,silverStock=SackStitcherMaker.silverStock,goldStock=SackStitcherMaker.goldStock,jewelStock=SackStitcherMaker.jewelStock,pearlStock=SackStitcherMaker.pearlStock,productStock=SackStitcherMaker.productStock,numBuildings=#SackStitcherMaker.buildings,hasMaker=SackStitcherMaker.maker~=nil,makerName=SackStitcherMaker.maker and SackStitcherMaker.maker.name or "—",makerSkill=SackStitcherMaker.maker and SackStitcherMaker.maker.skill or 0,activeMaking=#SackStitcherMaker.activeMaking,totalProducts=SackStitcherMaker.totalProducts} end
return SackStitcherMaker
